-- A missing implementation must fail before any mutation. Every successful test transaction is rolled back.
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF DB_NAME() NOT LIKE N'TC[_]Vuong[_]Test[_]%' OR OBJECT_ID('dbo.tc_vuong_test_fixture') IS NULL THROW 52790,'Isolated fixture required',1;
IF OBJECT_ID('dbo.fn_CalculateCommission') IS NULL THROW 52792,'Missing canonical commission implementation',1;
IF dbo.fn_CalculateCommission(1,50,0)<>1 THROW 52793,'HALF_UP VND rounding failed',1;
IF dbo.fn_CalculateCommission(0,50,500)<>0 THROW 52793,'Full refund commission failed',1;
IF dbo.fn_CalculateCommission(5,1,500)<>5 THROW 52793,'Commission cap failed',1;
IF dbo.fn_CalculateCommission(-1,50,0) IS NOT NULL THROW 52793,'Invalid input must be NULL',1;
BEGIN TRANSACTION;
DECLARE @actor uniqueidentifier=NEWID(),@buyer uniqueidentifier=NEWID(),@org uniqueidentifier=NEWID(),@event uniqueidentifier=NEWID(),@key uniqueidentifier=NEWID();
INSERT dbo.tc_users(id,email,user_name,full_name,platform_role) VALUES(@actor,CONCAT(@actor,'@test.invalid'),CONVERT(varchar(36),@actor),'Admin','ADMIN'),(@buyer,CONCAT(@buyer,'@test.invalid'),CONVERT(varchar(36),@buyer),'Buyer','CUSTOMER');
INSERT dbo.tc_organizations(id,name,contact_email) VALUES(@org,'A','a@test.invalid');
EXEC dbo.usp_CreateCommissionRule @org,@actor,@key,5,2,'2020-01-01','2099-01-01',0;
EXEC dbo.usp_CreateCommissionRule @org,@actor,@key,5,2,'2020-01-01','2099-01-01',0;
IF (SELECT COUNT(*) FROM dbo.tc_commission_rules WHERE organization_id=@org)<>1 THROW 52793,'Commission replay duplicated rule',1;
DECLARE @rule uniqueidentifier=(SELECT id FROM dbo.tc_commission_rules WHERE organization_id=@org);
INSERT dbo.tc_events(id,organization_id,commission_rule_id,title,end_time) VALUES(@event,@org,@rule,'Past Event','2020-01-01');
DECLARE @order uniqueidentifier=NEWID(),@payment uniqueidentifier=NEWID(),@extra uniqueidentifier=NEWID(),@refund uniqueidentifier=NEWID();
INSERT dbo.tc_orders(id,buyer_id,event_id,order_code,status,subtotal_amount,total_amount,paid_at) VALUES(@order,@buyer,@event,CONVERT(varchar(36),@order),'PAID',100,100,'2026-01-01');
INSERT dbo.tc_payments(id,order_id,amount,status,txn_ref,paid_at) VALUES(@payment,@order,100,'CAPTURED',CONVERT(varchar(36),@payment),'2026-01-01'),(@extra,@order,100,'CAPTURED',CONVERT(varchar(36),@extra),'2026-01-02');
UPDATE dbo.tc_orders SET accepted_payment_id=@payment WHERE id=@order;
INSERT dbo.tc_refunds(id,order_id,payment_id,amount,purpose,status,processed_at) VALUES(@refund,@order,@extra,100,'PAYMENT_COMPENSATION','COMPLETED','2026-01-03');
INSERT dbo.tc_refund_transfer_logs VALUES(NEWID(),@refund,1,'SUCCEEDED','COMP','2026-01-03',NULL);
EXEC dbo.usp_RecalculateSettlement @event,@actor,0;
DECLARE @settlement uniqueidentifier=(SELECT id FROM dbo.tc_settlements WHERE event_id=@event);
IF (SELECT gross_revenue FROM dbo.tc_settlements WHERE id=@settlement)<>100 OR (SELECT total_refund FROM dbo.tc_settlements WHERE id=@settlement)<>0 OR (SELECT total_commission FROM dbo.tc_settlements WHERE id=@settlement)<>7 THROW 52793,'Accepted revenue/compensation isolation failed',1;
IF (SELECT COUNT(*) FROM dbo.tc_settlement_order_snapshots WHERE settlement_id=@settlement)<>1 THROW 52793,'Order snapshot missing',1;
EXEC dbo.usp_ConfirmSettlement @settlement,@actor,0;
EXEC dbo.usp_ConfirmSettlement @settlement,@actor,0;
DECLARE @payout uniqueidentifier=NEWID(),@fp varbinary(32)=HASHBYTES('SHA2_256','terms');
EXEC dbo.usp_RecordPayout @settlement,@payout,@actor,40,'REF',NULL,@fp,0;
EXEC dbo.usp_RecordPayout @settlement,@payout,@actor,40,'REF',NULL,@fp,0;
EXEC dbo.usp_RecordPayout @settlement,@payout,@actor,40,'REF','UNKNOWN',@fp,0;
IF (SELECT pending_amount FROM dbo.tc_settlements WHERE id=@settlement)<>40 THROW 52793,'Replay/UNKNOWN reservation failed',1;
EXEC dbo.usp_RecordPayout @settlement,@payout,@actor,40,'REF','SUCCEEDED',@fp,0;
EXEC dbo.usp_RecordPayout @settlement,@payout,@actor,40,'REF','SUCCEEDED',@fp,0;
IF (SELECT paid_amount FROM dbo.tc_settlements WHERE id=@settlement)<>40 OR (SELECT pending_amount FROM dbo.tc_settlements WHERE id=@settlement)<>0 THROW 52793,'Terminal replay corrupted totals',1;
DECLARE @second uniqueidentifier=NEWID();
EXEC dbo.usp_RecordPayout @settlement,@second,@actor,53,'SECOND',NULL,@fp,0;
EXEC dbo.usp_RecordPayout @settlement,@second,@actor,53,'SECOND','FAILED',@fp,0;
IF (SELECT pending_amount FROM dbo.tc_settlements WHERE id=@settlement)<>0 THROW 52793,'FAILED did not release balance',1;
DECLARE @third uniqueidentifier=NEWID();
EXEC dbo.usp_RecordPayout @settlement,@third,@actor,53,'THIRD',NULL,@fp,0;
EXEC dbo.usp_RecordPayout @settlement,@third,@actor,53,'THIRD','SUCCEEDED',@fp,0;
IF (SELECT status FROM dbo.tc_settlements WHERE id=@settlement)<>'PAID' THROW 52793,'Full payout did not mark PAID',1;
IF (SELECT ticket_captured FROM dbo.fn_GetOrganizationCashFlow(@org,'2026-01-01','2026-02-01'))<>100 OR (SELECT compensation_captured FROM dbo.fn_GetOrganizationCashFlow(@org,'2026-01-01','2026-02-01'))<>100 OR (SELECT compensation_refund FROM dbo.fn_GetOrganizationCashFlow(@org,'2026-01-01','2026-02-01'))<>100 THROW 52793,'Cashflow classification failed',1;
IF (SELECT gross_revenue FROM dbo.fn_GetOrganizationRevenue(@org,'2026-01-01','2026-01-02'))<>100 THROW 52793,'Cohort boundary failed',1;
ROLLBACK;
PRINT 'PASS: rounding, accepted snapshots, compensation, confirmation replay, payout reserve/UNKNOWN/failure/success/replay, cohort and cashflow';
GO
